sources=json.loads((ROOT/'locales/sources.json').read_text(encoding='utf-8'))
english=json.loads((ROOT/'locales/en.json').read_text(encoding='utf-8'))['messages']
# Generic AST extraction also finds SQL fragments and old diagnostics. Leave the
# existing catalog intact; add only messages belonging to this update.
sources={k:v for k,v in sources.items() if k in english or k in M}
for k in M:sources.setdefault(k,['ui/setup-workflow.js','ui/profile-bulk.js','arena/profile_bulk.py','arena/setup_draft.py'])
sources['Engine Arena — 1.4.1']=['desktop/Program.cs']
for i,code in enumerate(['en','es','fr','de','pt','it','nl','pl']):
    p=ROOT/'locales'/f'{code}.json';data=json.loads(p.read_text(encoding='utf-8'))
    for k,v in M.items():
        assert len(v.split('|'))==7,k
        data['messages'][k]=k if i==0 else v.split('|')[i-1]
    data['messages']['Engine Arena — 1.4.1']='Engine Arena — 1.4.1'
    p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(ROOT/'locales/sources.json').write_text(json.dumps(sources,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
